import{c as t,Q as s,j as a,m as i}from"./chunks/framework.BOkOGOZz.js";const o="/screenshots/integrations-homer.png",g=JSON.parse('{"title":"Homer","description":"","frontmatter":{},"headers":[],"relativePath":"api/integrations/homer.md","filePath":"api/integrations/homer.md","lastUpdated":1788324030000}'),r={name:"api/integrations/homer.md"};function n(l,e,h,d,c,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="homer" tabindex="-1">Homer <a class="header-anchor" href="#homer" aria-label="Permalink to &quot;Homer&quot;">​</a></h1><p>LibrisLog can be integrated into <a href="https://github.com/bastienwirtz/homer" target="_blank" rel="noreferrer">Homer</a>, a self-hosted dashboard for your services, using its <a href="https://github.com/bastienwirtz/homer/blob/main/docs/customservices.md#librislog" target="_blank" rel="noreferrer">LibrisLog custom service</a>.</p><p>This smart card displays your reading statistics: total books, books read, currently reading, and want-to-read counts directly on your Homer dashboard.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A running LibrisLog instance reachable from the browser you use to view your Homer dashboard (the card fetches data client-side)</li><li>An <a href="/api/integrations/#api-keys">API key</a> with access to the statistics endpoint</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Add the following service entry to your Homer <code>config.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LibrisLog&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LibrisLog&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  logo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://docs.librislog.app/logo.png&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;LIBRISLOG-URL&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  apikey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;API-KEY&gt;&quot;</span></span></code></pre></div><p>The card supports auto refresh, which can be enabled individually for each service using the <code>updateIntervalMs</code> option.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Homer serves your <code>config.yml</code> at <code>/assets/config.yml</code> over HTTP. The API key in it is readable by anyone who can access your Homer instance. Only include it if your Homer instance is protected by authentication or access controls.</p></div><h2 id="placeholders" tabindex="-1">Placeholders <a class="header-anchor" href="#placeholders" aria-label="Permalink to &quot;Placeholders&quot;">​</a></h2><p>Replace the placeholders with your own values:</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;LIBRISLOG-URL&gt;</code></td><td><code>http://192.168.1.100:8000</code></td><td>The base URL of your LibrisLog instance (http or https)</td></tr><tr><td><code>&lt;API-KEY&gt;</code></td><td><code>lk_nRHsF3jxIBDa9u....</code></td><td>An API key with access to the statistics endpoint</td></tr><tr><td><code>&lt;HOMER-URL&gt;</code></td><td><code>http://192.168.1.100:8080</code></td><td>The base URL of your Homer instance</td></tr></tbody></table><h2 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h2><p>The Homer card fetches the API directly from the browser. You must add your Homer URL to the <a href="/guide/configuration.html#core-settings"><code>CORS_ORIGINS</code></a> environment variable of the LibrisLog backend:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CORS_ORIGINS=[&quot;&lt;HOMER-URL&gt;&quot;]</span></span></code></pre></div><p>If the card stays empty or shows no statistics, check your browser console for CORS errors.</p><h2 id="result" tabindex="-1">Result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Result&quot;">​</a></h2><p><img src="`+o+'" alt="Homer Widget" loading="lazy"></p>',19)])])}const k=t(r,[["render",n]]);export{g as __pageData,k as default};
